pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount) public {
        // Admissible domain: depositAmount > 0 so there is something to withdraw
        vm.assume(depositAmount > 0);
        vm.assume(depositAmount <= address(this).balance / 2);

        // Fund a fuzzed actor and make a deposit
        address actor = address(0x100);
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // Record balance before withdrawal
        uint256 balanceBefore = address(c).balance;

        // Perform withdrawal as the same actor
        vm.prank(actor);
        c.withdrawAll();

        // After withdrawal, the contract balance should be reduced by exactly depositAmount
        assertTrue(address(c).balance == balanceBefore - depositAmount);
    }
}

