import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address depositor, address other) public {
        vm.assume(amount > 0);
        vm.assume(depositor != other);
        vm.assume(depositor != address(0) && other != address(0));

        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.deposit{value: amount}();

        vm.prank(depositor);
        c.withdrawAll();

        // After the original withdrawAll, credit[depositor] is 0 and credit[other] is 0.
        // Now other tries to withdrawAll (should withdraw 0, so no balance change).
        // The reference correctly has balance matching the sum of remaining credits (0),
        // therefore a withdrawAll by other leaves balance unchanged.
        // The mutant's balance is inflated by 1 wei, so it can be partially drained.
        uint256 balBefore = address(c).balance;
        vm.prank(other);
        try c.withdrawAll() {} catch {}
        uint256 balAfter = address(c).balance;

        // The general rule: if all credits are zero, a withdrawAll by any address must
        // not change the contract's ETH balance. The mutant breaks this because it
        // leaves a 1-wei excess that becomes withdrawable by other.
        assertEq(balBefore, balAfter);
    }
}

