pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 depositAmount, uint96 withdrawCallCount) public {
        // Restrict: need at least one deposit and at least one withdrawal attempt
        vm.assume(depositAmount > 0);
        vm.assume(withdrawCallCount >= 1 && withdrawCallCount <= 10);
        // Adversarial counterparty: a reentrant attacker that repeatedly calls withdrawAll
        ReentrantAttacker attacker = new ReentrantAttacker(c, withdrawCallCount);
        address actor = address(attacker);
        vm.deal(actor, depositAmount);
        // Actor deposits
        vm.prank(actor);
        c.deposit{value: depositAmount}();
        // Record initial contract ETH balance after deposit
        uint256 initialContractBalance = address(c).balance;
        // Actor calls withdrawAll, which triggers reentrant repeated withdrawals
        bool ok;
        try attacker.attack() {
            ok = true;
        } catch {
            ok = false;
        }
        // The attacker's attack may revert because the contract's balance might be insufficient
        // We only care about the state of the reference contract, which should never revert and must maintain balance invariant
        // For the reference contract, after a successful attack (reverts not from failing balance but from zero credit or reentrancy ending),
        // the contract's ETH balance should equal its recorded balance variable.
        // Since the reentrant attacker only withdraws up to the initial credit, the reference should never overpay.
        // Assert: if the attack did not revert due to insufficient balance (i.e., the call succeeded),
        // then the contract's balance should equal its internal balance variable.
        assertTrue(address(c).balance == c.balance());
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public withdrawalCount;
    uint256 public maxWithdrawals;
    constructor(C _target, uint256 _maxWithdrawals) {
        target = _target;
        maxWithdrawals = _maxWithdrawals;
        withdrawalCount = 0;
    }
    function attack() external {
        target.withdrawAll();
    }
    receive() external payable {
        if (withdrawalCount < maxWithdrawals) {
            withdrawalCount++;
            target.withdrawAll();
        }
    }
}

