pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositA, uint256 depositB, uint256 withdrawA) public {
        // Bound deposits to a reasonable range to avoid overflow and ensure we have a valid test domain
        depositA = bound(depositA, 1, 100 ether);
        depositB = bound(depositB, 1, 100 ether);
        withdrawA = bound(withdrawA, 1, 100 ether);

        // Create two distinct depositors
        address alice = address(0x1);
        address bob = address(0x2);

        // Fund Alice and Bob
        vm.deal(alice, depositA + depositB);
        vm.deal(bob, depositB);

        // Alice deposits depositA
        vm.prank(alice);
        c.deposit{value: depositA}();

        // Bob deposits depositB
        vm.prank(bob);
        c.deposit{value: depositB}();

        // Alice withdraws up to withdrawA (capped at her actual credit via internal logic)
        vm.prank(alice);
        try c.withdrawAll() { } catch { }

        // Bob should always be able to withdraw his full deposit (depositB).
        // In the buggy version, the contract balance is not decremented on withdrawal,
        // but the credit IS decremented. Thus after Alice withdraws, the total credits
        // are correct (Alice's credit reduced, Bob's credit intact), but the contract
        // ETH balance is higher than the sum of credits. However, future withdrawals
        // will still succeed because balance is artificially high.
        // Actually, the bug *prevents* balance from being decremented, so balance > sum(credits).
        // The invariant violated is: a deposit-and-withdraw sequence should leave the contract
        // with balance exactly equal to sum of credits. After any operation, sum(credits) <= balance.
        // In the correct version, balance is decremented, so sum(credits) == balance.
        // In the buggy version, sum(credits) < balance after the first withdrawal.
        // So the property: after Bob withdraws, his balance should increase by exactly depositB.
        // We measure Bob's balance before and after his withdrawal.
        uint256 bobBalanceBefore = bob.balance;
        vm.prank(bob);
        try c.withdrawAll() { } catch { }
        uint256 bobBalanceAfter = bob.balance;

        // Bob should receive his full credit (depositB), so his balance after = before + depositB.
        // In the buggy version, balance is not decremented, but credits are, so Bob still gets his depositB.
        // The property above does not break.
        // Need a property that actually breaks: the contract's ETH balance should never be less than the sum of credits.
        // But that holds in both? Let's think...
        // P: balance = total_deposits - total_withdrawals_paid
        // M: balance = total_deposits - 0 (since balance never decremented)
        // After Alice withdraws w, in P: balance = depositA+depositB - w, credits: Alice credit = depositA-w, Bob = depositB => sum = depositA+depositB - w = balance
        // In M: balance = depositA+depositB, credits same => sum = depositA+depositB - w < balance. So balance > sum credits.
        // This alone doesn't cause a revert. But if many withdrawals happen, eventually credits sum to zero (all withdrawn), but balance still has all deposits.
        // That violates an invariant but no revert. The property we need is about the contract's ability to pay all credits.
        // Actually, the invariant "balance >= sum(credits)" holds in both, but in M balance > sum credits after withdraw.
        // The property that breaks: after all depositors withdraw, the contract balance should be zero. In M it's non-zero.
        // But the test must use a view/getter. There is no public getter for sum of credits.
        // Instead, we can check that a second withdrawal by the same depositor should revert (credit is 0) and it does in both.
        // We need a property that is universal and breaks for the bug. The bug is "balance not decremented". 
        // The effect is that the contract holds more ETH than it owes. That doesn't directly affect external callers until... 
        // Wait! The contract uses `call{value: oCredit}` to send ETH. If the contract's balance is less than oCredit, the call fails.
        // In P: balance is decremented, so balance remains exactly equal to total credits. So any withdrawal can always be paid.
        // In M: balance never decreases, so balance is always >= total credits, so payments never fail due to insufficient balance.
        // So that's not the issue.
        // Then what observable difference exists? The difference is in the state variable `balance` which is public? In the given contract, `uint balance;` is not declared public, so no auto-getter. So we cannot read it directly.
        // We can only observe via `address(c).balance`. In P, after all credits withdrawn, contract balance = 0. In M, contract balance > 0.
        // So the universal rule: "After all depositors have withdrawn their full credit, the contract's ETH balance must be zero."
        // But we have two depositors; we need to let both withdrawAll. Then check address(c).balance == 0.
        // In P: true. In M: false.
        // We need to ensure both depositors withdraw. Alice already withdrawn, Bob will withdraw.
        // After Bob withdraws, both credits are zero. Then address(c).balance should be 0.
        // Let's implement that.
        vm.prank(alice);
        c.withdrawAll(); // already tried above but we can do it again; it will withdraw 0 if credit is 0, no effect
        vm.prank(bob);
        c.withdrawAll(); // Bob withdraws depositB

        // Now both credits are zero, and in the correct contract, balance is 0.
        assertTrue(address(c).balance == 0);
    }
}

