pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    event TransferOccurred(bool occurred);

    function setUp() public { 
        c = new C();
    }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawCallerSeed) public {
        // Restrict deposit amount to avoid overflow and keep domain wide
        depositAmount = bound(depositAmount, 0, 1000 ether);
        // Use seed to create a deterministic but fuzzed actor for withdrawal
        address callerWithNoCredit = address(uint160(uint256(keccak256(abi.encode(withdrawCallerSeed)))));
        vm.assume(callerWithNoCredit != address(0) && callerWithNoCredit != address(this));

        // Deploy a spy helper that will report whether it received any ETH
        Spy spy = new Spy();

        // Set up: another actor deposits some ETH to ensure c has balance, but our target caller has no credit
        address depositor = address(0x1234);
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.deposit{value: depositAmount}();

        // The target caller with no credit triggers withdrawAll
        vm.prank(callerWithNoCredit);
        c.withdrawAll();

        // Now we need to check if a zero-value call to the caller occurred.
        // Since we cannot spy on callbacks to an externally-owned address, we repeat the test
        // but route the call to our Spy contract by having the spy call withdrawAll on behalf of the caller.
        // Actually, we need the contract to call *the caller*, which is an EOA. We can't change the target of the low-level call in C.
        // The bug is that C performs `call{value: 0}("")` to msg.sender (an EOA with no code).
        // A low-level call to an EOA always succeeds and does nothing. We can detect it only by gas or by a re-entrancy guard / self-spying.
        // The general rule: 'When credit[msg.sender] == 0, the contract must not attempt any external call'.
        // We cannot observe this difference directly from the public surface of C after the fact because the state changes are identical:
        // balance -= 0, credit = 0. The only observable difference is the gas consumed by the extraneous call.
        // Gas is not a reliable fuzz target. However, we can detect the extraneous call by wrapping the caller in a contract that records whether its fallback was invoked.
        // The problem says: if the difference manifests through behaviour of an external party, the fuzzer CANNOT synthesise that party from a raw address,
        // and we MUST deploy a helper. Here we deploy a helper that acts as the withdrawer, and whose fallback records the call.
        // Since the low-level call in C is to msg.sender, we make the helper contract the msg.sender.

        // Redo: use helper as msg.sender
        vm.startPrank(address(spy));
        c.withdrawAll();
        vm.stopPrank();

        // Assert that no transfer occurred (spy's fallback was not triggered with any value)
        // The reference C (oCredit > 0) will not call because credit[spy] == 0, so spy.lastReceivedAmount == 0 (initial).
        // The buggy C (oCredit >= 0) will call with value 0, so spy.lastReceivedAmount will be updated to 0 and lastCaller will be non-zero.
        // We check that no call was made at all, i.e., spy.lastCaller == address(0) (or lastReceivedAmount remained max uint indicating no call).
        assertTrue(spy.wasCalled() == false, "External call should not occur when credit is zero");
    }
}

contract Spy {
    bool public called;
    uint256 public lastReceivedAmount;
    address public lastCaller;

    fallback() external payable {
        called = true;
        lastReceivedAmount = msg.value;
        lastCaller = msg.sender;
    }

    receive() external payable {
        called = true;
        lastReceivedAmount = msg.value;
        lastCaller = msg.sender;
    }

    function wasCalled() external view returns (bool) {
        return called;
    }
}

