        // We deploy a helper that accepts Ether and returns true, being a contract (code present) that does NOT revert.
        // This complies with the rule while letting the fuzzer explore the space freely.
        Receiver helper = new Receiver();
        address adversary = address(helper);

        // Have the adversary deposit and attempt withdrawal
        vm.deal(adversary, depositAmount);
        vm.prank(adversary);
        c.deposit{value: depositAmount}();

        // Drive withdrawAll as the adversary: the helper receives Ether, so the low-level call succeeds.
        // (The reference contract will set credit to 0; the buggy one will not.)
        vm.prank(adversary);
        c.withdrawAll();

