        // Therefore assert that the balance after the second call is exactly the same as before the second call.
        // This fundamentally relies on the fact that a caller's credit is reduced to 0 after a successful withdrawal in the reference.
        uint256 balanceAfterSecond = address(c).balance;
        assertTrue(balanceAfterSecond == balanceBeforeSecond);
